"""Genera ciencia-salud/dieta-inflamacion/index.html (ES/EN/FR)."""
import sys, pathlib
from healthkit import t, section, ref, legend, page

OUT = pathlib.Path(sys.argv[1])
S = []

S.append(section(t('Lo que dicen las guías', 'What the guidelines say', 'Ce que disent les recommandations'), '\n'.join([
    ref('Hashash JG, Elkins J, Lewis JD, Binion DG · Gastroenterology · 2024; 166(3): 521–532',
        'AGA Clinical Practice Update on Diet and Nutritional Therapies in Patients With Inflammatory Bowel Disease: Expert Review',
        t('La Asociación Americana de Gastroenterología recomienda a los adultos con enfermedad inflamatoria intestinal (EII) una dieta mediterránea, salvo contraindicación, con poca sal, poco azúcar y pocos ultraprocesados. Una dieta baja en carne roja y procesada podría reducir los brotes de colitis ulcerosa, aunque no se ha demostrado en Crohn. Advierte de que evitar alimentos sanos como la fibra por miedo puede empobrecer la dieta incluso en remisión, y que quien tiene estrecheces del intestino tolera mejor frutas y verduras cocidas o bien masticadas.',
          'The American Gastroenterological Association recommends a Mediterranean diet for adults with inflammatory bowel disease (IBD), unless contraindicated, low in salt, sugar and ultra-processed food. A diet low in red and processed meat may reduce ulcerative colitis flares, though this hasn’t been shown in Crohn’s. It warns that avoiding healthy foods such as fibre out of fear can impoverish the diet even in remission, and that people with intestinal strictures tolerate fruit and vegetables better when cooked or well chewed.',
          'L’Association américaine de gastroentérologie recommande aux adultes atteints de maladies inflammatoires chroniques de l’intestin (MICI) un régime méditerranéen, sauf contre-indication, pauvre en sel, en sucre et en ultra-transformés. Un régime pauvre en viande rouge et transformée pourrait réduire les poussées de rectocolite hémorragique, sans preuve pour la maladie de Crohn. Elle prévient qu’éviter par crainte des aliments sains comme les fibres peut appauvrir l’alimentation même en rémission, et que les personnes ayant un rétrécissement intestinal tolèrent mieux les fruits et légumes cuits ou bien mâchés.'),
        ['gui'], doi='10.1053/j.gastro.2023.11.303'),
    ref('Levine A, Rhodes JM, Lindsay JO, et al. · Clinical Gastroenterology and Hepatology · 2020; 18(6): 1381–1392',
        'Dietary Guidance From the International Organization for the Study of Inflammatory Bowel Diseases',
        t('El panel internacional IOIBD recomienda limitar los emulsionantes carboximetilcelulosa (E-466) y polisorbato 80 (E-433), el carragenano (E-407), la maltodextrina, los edulcorantes artificiales, el dióxido de titanio y los sulfitos, y evitar las grasas trans y los lácteos sin pasteurizar. En Crohn, aconseja más frutas y verduras y menos grasas saturadas. En colitis ulcerosa, más omega-3 del pescado (no en suplementos), menos carne roja y procesada, y menos ácido mirístico, una grasa del aceite de palma, el de coco y la grasa láctea.',
          'The international IOIBD panel recommends limiting the emulsifiers carboxymethylcellulose (E466) and polysorbate 80 (E433), carrageenan (E407), maltodextrin, artificial sweeteners, titanium dioxide and sulphites, and avoiding trans fats and unpasteurised dairy. In Crohn’s, it advises more fruit and vegetables and less saturated fat. In ulcerative colitis, more omega-3 from fish (not supplements), less red and processed meat, and less myristic acid, a fat found in palm oil, coconut oil and dairy fat.',
          'Le panel international IOIBD recommande de limiter les émulsifiants carboxyméthylcellulose (E466) et polysorbate 80 (E433), le carraghénane (E407), la maltodextrine, les édulcorants artificiels, le dioxyde de titane et les sulfites, et d’éviter les graisses trans et les produits laitiers non pasteurisés. Dans la maladie de Crohn, il conseille plus de fruits et légumes et moins de graisses saturées. Dans la rectocolite hémorragique, plus d’oméga-3 issus du poisson (pas en compléments), moins de viande rouge et transformée, et moins d’acide myristique, une graisse présente dans l’huile de palme, l’huile de coco et la matière grasse laitière.'),
        ['gui'], doi='10.1016/j.cgh.2020.01.046'),
]), t('Las guías se apoyan en evidencia «de calidad variable», como dice la propia IOIBD: muchas recomendaciones vienen de estudios observacionales y de experimentos en animales. La propia AGA reconoce que ninguna dieta ha reducido de forma constante los brotes en adultos con EII. La evidencia sobre los emulsionantes, con el ensayo ADDapt, está en el tema «Intestino inflamado, microbiota empobrecida».',
      'The guidelines rest on evidence “of varying quality”, as the IOIBD itself says: many recommendations come from observational studies and animal experiments. The AGA itself acknowledges that no diet has consistently reduced flares in adults with IBD. The evidence on emulsifiers, including the ADDapt trial, is in the topic “Inflamed gut, depleted microbiota”.',
      'Les recommandations reposent sur des preuves « de qualité variable », comme le dit l’IOIBD elle-même : beaucoup viennent d’études observationnelles et d’expériences animales. L’AGA reconnaît qu’aucun régime n’a réduit de façon constante les poussées chez l’adulte atteint de MICI. Les preuves sur les émulsifiants, avec l’essai ADDapt, sont dans le sujet « Intestin enflammé, microbiote appauvri ».')))

S.append(section(t('Dieta mediterránea', 'Mediterranean diet', 'Régime méditerranéen'), '\n'.join([
    ref('Khalili H, Håkansson N, Chan SS, et al. · Gut · 2020; 69(9): 1637',
        'Adherence to a Mediterranean diet is associated with a lower risk of later-onset Crohn’s disease: results from two large prospective cohort studies',
        t('83 147 adultos suecos de 45 a 79 años, seguidos una media de 17 años. Quienes seguían más la dieta mediterránea tuvieron un 58 % menos riesgo de desarrollar Crohn que quienes la seguían menos (HR 0,42). No hubo relación con la colitis ulcerosa (HR 1,08). Los autores estiman que la mala adherencia explicaría un 12 % de los casos de Crohn de inicio tardío.',
          '83,147 Swedish adults aged 45 to 79, followed for an average of 17 years. Those who followed the Mediterranean diet most closely had a 58% lower risk of developing Crohn’s than those who followed it least (HR 0.42). There was no link with ulcerative colitis (HR 1.08). The authors estimate that poor adherence would explain 12% of later-onset Crohn’s cases.',
          '83 147 adultes suédois de 45 à 79 ans, suivis en moyenne 17 ans. Ceux qui suivaient le plus le régime méditerranéen avaient un risque de Crohn 58 % plus faible que ceux qui le suivaient le moins (HR 0,42). Aucun lien avec la rectocolite hémorragique (HR 1,08). Les auteurs estiment qu’une mauvaise adhésion expliquerait 12 % des cas de Crohn d’apparition tardive.'),
        ['obs'], url='https://gut.bmj.com/content/69/9/1637', label='gut.bmj.com/content/69/9/1637'),
    ref('Lewis JD, Sandler RS, Brotherton C, et al. (DINE-CD) · Gastroenterology · 2021; 161(3): 837–852.e9',
        'A Randomized Trial Comparing the Specific Carbohydrate Diet to a Mediterranean Diet in Adults With Crohn’s Disease',
        t('194 adultos con Crohn leve o moderado siguieron durante 12 semanas la dieta mediterránea o una dieta restrictiva muy popular (la «dieta de carbohidratos específicos»); las 6 primeras semanas recibieron la comida preparada. A las 6 semanas, entraron en remisión de síntomas un 43,5 % con la mediterránea y un 46,5 % con la restrictiva, sin diferencia entre ellas. Como la mediterránea es más fácil de seguir y tiene otros beneficios, los autores la consideran preferible para la mayoría.',
          '194 adults with mild to moderate Crohn’s followed either the Mediterranean diet or a popular restrictive diet (the “specific carbohydrate diet”) for 12 weeks; for the first 6 weeks their meals were provided. At 6 weeks, 43.5% on the Mediterranean diet and 46.5% on the restrictive one reached symptom remission, with no difference between them. Since the Mediterranean diet is easier to follow and has other benefits, the authors consider it preferable for most people.',
          '194 adultes atteints de maladie de Crohn légère à modérée ont suivi pendant 12 semaines le régime méditerranéen ou un régime restrictif très populaire (le « régime de glucides spécifiques ») ; les 6 premières semaines, les repas étaient fournis. À 6 semaines, 43,5 % sous régime méditerranéen et 46,5 % sous régime restrictif étaient en rémission des symptômes, sans différence entre eux. Le méditerranéen étant plus facile à suivre et ayant d’autres bénéfices, les auteurs le jugent préférable pour la plupart.'),
        ['rct'], doi='10.1053/j.gastro.2021.05.047'),
]), t('Khalili es una cohorte: muestra asociación, no causa, y solo hubo 164 casos de Crohn, así que el tamaño exacto del efecto es incierto (intervalo de 0,22 a 0,80). Estudió el Crohn de inicio tardío, no a personas jóvenes. DINE-CD no tenía un grupo sin dieta, y casi no hubo mejoras en los marcadores de inflamación (PCR y calprotectina) con ninguna de las dos. Ojo también a un patrón: tanto la dieta mediterránea como los ultraprocesados se relacionan con el Crohn, pero no con la colitis ulcerosa.',
      'Khalili is a cohort: it shows association, not cause, and there were only 164 Crohn’s cases, so the exact size of the effect is uncertain (interval 0.22 to 0.80). It studied later-onset Crohn’s, not young people. DINE-CD had no no-diet group, and there was hardly any improvement in inflammation markers (CRP and calprotectin) with either diet. Note a pattern too: both the Mediterranean diet and ultra-processed food are linked to Crohn’s but not to ulcerative colitis.',
      'Khalili est une cohorte : elle montre une association, pas une cause, et il n’y a eu que 164 cas de Crohn, donc la taille exacte de l’effet reste incertaine (intervalle de 0,22 à 0,80). Elle portait sur le Crohn d’apparition tardive, pas sur les jeunes. DINE-CD n’avait pas de groupe sans régime, et les marqueurs d’inflammation (CRP et calprotectine) ont à peine bougé avec l’un ou l’autre. À noter aussi : le régime méditerranéen comme les ultra-transformés sont liés au Crohn, mais pas à la rectocolite hémorragique.')))

S.append(section(t('Fermentados', 'Fermented foods', 'Aliments fermentés'), '\n'.join([
    ref('Wastyk HC, Fragiadakis GK, Perelman D, et al. · Cell · 2021; 184(16): 4137–4153.e14',
        'Gut-microbiota-targeted diets modulate human immune status',
        t('36 adultos sanos durante 10 semanas: una dieta rica en fermentados (unas 6 raciones al día de yogur, kéfir, chucrut, kimchi y similares) aumentó la diversidad de la microbiota y bajó 19 marcadores inflamatorios en sangre, entre ellos la interleucina 6. La dieta alta en fibra no cambió la diversidad en ese plazo.',
          '36 healthy adults over 10 weeks: a diet rich in fermented foods (about 6 servings a day of yoghurt, kefir, sauerkraut, kimchi and similar) increased microbiota diversity and lowered 19 inflammatory markers in the blood, interleukin-6 among them. The high-fibre diet didn’t change diversity in that time.',
          '36 adultes en bonne santé pendant 10 semaines : un régime riche en aliments fermentés (environ 6 portions par jour de yaourt, kéfir, choucroute, kimchi et similaires) a augmenté la diversité du microbiote et fait baisser 19 marqueurs inflammatoires sanguins, dont l’interleukine 6. Le régime riche en fibres n’a pas modifié la diversité sur cette durée.'),
        ['rct'], doi='10.1016/j.cell.2021.06.019'),
]), t('Fue un ensayo pequeño en personas sanas, no en pacientes con EII, y su desenlace principal (una puntuación de respuesta inmune) no cambió. Que la fibra no subiera la diversidad en 10 semanas no significa que no sirva: es el alimento de las bacterias que fabrican butirato.',
      'It was a small trial in healthy people, not IBD patients, and its primary outcome (an immune response score) didn’t change. Fibre not raising diversity in 10 weeks doesn’t mean it’s useless: it feeds the bacteria that make butyrate.',
      'C’était un petit essai chez des personnes en bonne santé, pas chez des patients atteints de MICI, et son critère principal (un score de réponse immunitaire) n’a pas changé. Que les fibres n’aient pas augmenté la diversité en 10 semaines ne veut pas dire qu’elles ne servent à rien : elles nourrissent les bactéries qui fabriquent le butyrate.')))

html = page(
    title_tag='Dieta e inflamación del colon',
    description='Las fuentes detrás de la story sobre qué comida aviva la inflamación del colon y cuál la calma: guías AGA e IOIBD, dieta mediterránea y fermentados. / The sources behind the story on diet and colon inflammation.',
    h1=t('Qué comida inflama tu colon y cuál lo calma: <em>las fuentes</em>', 'Which foods inflame your colon and which calm it: <em>the sources</em>', 'Quels aliments enflamment ton côlon et lesquels l’apaisent&nbsp;: <em>les sources</em>'),
    lede=t('Las recomendaciones de la story vienen sobre todo de dos guías clínicas para la enfermedad inflamatoria intestinal, más los estudios que las respaldan. Aquí está cada una, con el tipo de evidencia y lo que no demuestra. Casi todo se ha estudiado en personas con EII; en la población general, la relación entre dieta e inflamación del colon es menos directa.',
           'The story’s recommendations come mainly from two clinical guidelines for inflammatory bowel disease, plus the studies behind them. Here is each one, with the type of evidence and what it doesn’t show. Almost all of it was studied in people with IBD; in the general population, the link between diet and colon inflammation is less direct.',
           'Les recommandations de la story viennent surtout de deux recommandations cliniques pour les MICI, plus les études qui les soutiennent. Voici chacune, avec le type de preuve et ce qu’elle ne montre pas. Presque tout a été étudié chez des personnes atteintes de MICI ; dans la population générale, le lien entre alimentation et inflammation du côlon est moins direct.'),
    legend_html=legend(['gui', 'rct', 'obs'], old=False),
    sections=S,
    alt='Las stories en español, inglés y francés: ¿Qué comida inflama tu colon y cuál lo calma? / Which foods inflame your colon and which calm it? / Quels aliments enflamment ton côlon et lesquels l’apaisent ?',
    footer=t('Contenido divulgativo; no sustituye el consejo médico. Si tienes EII, consulta cualquier cambio de dieta con tu equipo médico o un dietista: la comida acompaña al tratamiento, no lo sustituye.',
             'For general information only, not medical advice. If you have IBD, discuss any diet change with your care team or a dietitian: food supports treatment, it doesn’t replace it.',
             'Contenu de vulgarisation, pas un avis médical. Si vous avez une MICI, parlez de tout changement alimentaire à votre équipe médicale ou à un diététicien : l’alimentation accompagne le traitement, elle ne le remplace pas.'),
)
(OUT / 'index.html').write_text(html)
print('ok', len(html))
